def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    recent_start = n - 10
    if recent_start < 0:
        recent_start = 0
    recent_c = 0
    for i in range(n):
        b = history[i][1]
        if b == 'C':
            opp_c += 1
            if i >= recent_start:
                recent_c += 1

    overall_opp = opp_c / n
    recent_len = n - recent_start
    recent_opp = recent_c / recent_len

    def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            def_streak += 1
        else:
            break

    mutual_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            mutual_streak += 1
        else:
            break

    cntC = [[0.0, 0.0], [0.0, 0.0]]
    cntT = [[0.0, 0.0], [0.0, 0.0]]

    hostile_all = 0
    after_D = 0
    punish_after_D = 0

    window = 60
    trans_end = n - 1
    for t in range(trans_end):
        pm, po = history[t]
        no = history[t + 1][1]

        if pm == 'C' and no == 'D':
            hostile_all += 1
        if pm == 'D':
            after_D += 1
            if no == 'D':
                punish_after_D += 1

        if t >= trans_end - window:
            a = 0 if pm == 'C' else 1
            b = 0 if po == 'C' else 1
            cntT[a][b] += 1.0
            if no == 'C':
                cntC[a][b] += 1.0

    priorW = 4.0
    pCC = (cntC[0][0] + 0.85 * priorW) / (cntT[0][0] + priorW)
    pCD = (cntC[0][1] + 0.70 * priorW) / (cntT[0][1] + priorW)
    pDC = (cntC[1][0] + 0.25 * priorW) / (cntT[1][0] + priorW)
    pDD = (cntC[1][1] + 0.35 * priorW) / (cntT[1][1] + priorW)

    h = 100 - n
    if h == 1:
        return 'D'

    vC = 5.0
    vD = 1.0
    actC = 1
    actD = 1

    for _ in range(2, h + 1):
        optCC_C = 3.0 + pCC * vC + (1.0 - pCC) * vD
        optDC_C = 5.0 + pDC * vC + (1.0 - pDC) * vD
        if optCC_C + 0.20 >= optDC_C:
            newC = optCC_C
            aC = 0
        else:
            newC = optDC_C
            aC = 1

        optCD_D = 0.0 + pCD * vC + (1.0 - pCD) * vD
        optDD_D = 1.0 + pDD * vC + (1.0 - pDD) * vD
        if optCD_D + 0.20 >= optDD_D:
            newD = optCD_D
            aD = 0
        else:
            newD = optDD_D
            aD = 1

        vC = newC
        vD = newD
        actC = aC
        actD = aD

    if last_opp == 'C':
        action = 'C' if actC == 0 else 'D'
    else:
        action = 'C' if actD == 0 else 'D'

    if action == 'C' and last_opp == 'D':
        if (def_streak >= 2 and overall_opp <= 0.30) or (def_streak >= 3 and recent_opp <= 0.35) or (def_streak >= 5 and overall_opp <= 0.60):
            action = 'D'

    if action == 'C' and last_me == 'D' and last_opp == 'D' and mutual_streak >= 5 and recent_opp <= 0.25:
        action = 'D'

    if action == 'D' and last_me == 'D' and last_opp == 'D' and mutual_streak >= 2:
        if overall_opp >= 0.55 and recent_opp >= 0.35 and hostile_all <= 3:
            if rng.random() < 0.10:
                action = 'C'

    if action == 'C' and last_opp == 'C' and recent_opp >= 0.65:
        if hostile_all == 0 and after_D >= 1 and punish_after_D == 0:
            action = 'D'
        elif overall_opp >= 0.85 and recent_opp >= 0.85 and after_D == 0 and 35 <= n <= 92:
            if rng.random() < 0.07:
                action = 'D'
        elif after_D == 0 and recent_opp >= 0.90 and n >= 50:
            if rng.random() < 0.03:
                action = 'D'

    return action
